java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
net.coobird.thumbnailator.tasks.io.OutputStreamImageSink sink = new net.coobird.thumbnailator.tasks.io.OutputStreamImageSink(baos);
sink.setOutputFormatName("png");

try {
    sink.write(sourceImage);
} catch (net.coobird.thumbnailator.tasks.UnsupportedFormatException e) {
    System.err.println("Format not supported by JVM Image I/O: " + e.getMessage());
    return;
} catch (java.io.IOException e) {
    System.err.println("Failed to write thumbnail: " + e.getMessage());
    return;
}

byte[] data = baos.toByteArray();
assert data.length > 0 : "Output data should not be empty";

java.awt.image.BufferedImage readBack;
try {
    readBack = javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(data));
} catch (java.io.IOException e) {
    throw new RuntimeException("Failed to read back image", e);
}

assert readBack != null : "Should be able to read back the image";
assert readBack.getWidth() == sourceImage.getWidth() : "Width should match";
assert readBack.getHeight() == sourceImage.getHeight() : "Height should match";

System.out.println("__CHECK__ write " + data.length);
